// Backups stay inside the vault and use only Obsidian's adapter API.
const WORKBENCH_BACKUP_ROOT='工作台备份';
async function createVaultBackup(store,manual=false){
 if(store.backing)return null;
 store.backing=true;
 const {vault}=store.app,a=vault.adapter;
 const safe=p=>{if(typeof p!=='string'||!p||p.startsWith('/')||p.includes('\\')||p.split('/').some(x=>!x||x==='.'||x==='..')||/^[A-Za-z]:/.test(p))throw Error('备份路径无效');return p;};
 const mkdir=async p=>{let current='';for(const part of safe(p).split('/')){current=current?current+'/'+part:part;if(!await a.exists(current))await a.mkdir(current);}};
 try{
  const day=new Date().toLocaleDateString('en-CA');
  const daily=WORKBENCH_BACKUP_ROOT+'/'+day;
  const marker=daily+'/完成.json';
  if(!manual&&await a.exists(marker)){const previous=JSON.parse(await a.read(marker));store.lastBackup=previous.created;return {path:daily,skipped:true};}
  let dest=manual?daily+'-'+Date.now():daily;
  if(manual){const base=dest;let n=1;while(await a.exists(dest))dest=base+'-'+n++;}
  const writeText=async(p,text)=>{safe(p);await mkdir(p.slice(0,p.lastIndexOf('/')));await a.write(p,text);};
  const writeBinary=async(p,data)=>{safe(p);await mkdir(p.slice(0,p.lastIndexOf('/')));await a.writeBinary(p,data);};
  // Capture the source list before any backup files are created. Never include backups.
  const files=vault.getFiles().filter(f=>store.ownsBackupPath(f.path)&&f.path!==WORKBENCH_BACKUP_ROOT&&!f.path.startsWith(WORKBENCH_BACKUP_ROOT+'/'));
  const entries=[];
  for(const file of files){safe(file.path);const data=await vault.readBinary(file);await writeBinary(dest+'/vault/'+file.path,data);entries.push({path:file.path,bytes:data.byteLength});}
  const pluginDir=safe(vault.configDir+'/plugins/'+store.plugin.manifest.id);
  for(const name of ['main.js','manifest.json','styles.css','系统文件快照（系统）.json']){
   const source=pluginDir+'/'+name;if(!await a.exists(source))continue;
   const text=await a.read(source);await writeText(dest+'/vault/'+source,text);
   entries.push({path:source,bytes:new TextEncoder().encode(text).byteLength});
  }
  const created=new Date().toISOString();
  // A backup is valid only after every copy succeeds; incomplete folders can be retried.
  await writeText(dest+'/完成.json',JSON.stringify({version:2,root:store.backupSourceRoot(),created,files:entries},null,2));
  store.lastBackup=created;
  return {path:dest,skipped:false,files:entries.length};
 }finally{store.backing=false;}
}

