   const row=wrap.createDiv({cls:'pw-inline'});for(const type of list(f.target))button(row,'＋新建'+this.store.typeLabel(type),()=>{this.pull();new RecordForm(this.store,type,null,{},created=>{this.fm[f.name]=wikilink(created.file.path);this.draw()}).open()});
